```js
preparseOwnAliasEntry(alias, def) {
    const firstParamIndex = alias.indexOf("<");
    if (firstParamIndex === -1) {
        if (hasArkKind(def, "module") || hasArkKind(def, "generic"))
            return [alias, def];
        const qualifiedName = ...;
        const config = this.resolvedConfig.keywords?.[qualifiedName];
        if (config)
